-- ── engine/pkg/models/trade_order/trade_order_status.sql ─────────────────────────────────────────────

-- Model of states that a trade order can undergo during its
-- lifecycle. Transitional states hold funds in `currency_account.amount_reserved`
-- Final states should release all reserved funds.
CREATE TYPE trade_order_status AS ENUM(
    -- TRANSITIONAL STATES
    -- order remains in the order book and has no fills
    'OPEN',
    -- order remains in the order book but with partial fill
    'PARTIALLY_FILLED',
    -- FINAL STATES
    -- order has been cancelled by the user without any fills
    'CANCELLED',
    -- order has been partially filled but then cancelled by user
    'PARTIALLY_CANCELLED',
    -- order has been partially filled but then rejected.
    -- Possible rejection reasons:
    --  * IOC
    --  * GTD
    --  * GTT
    'PARTIALLY_REJECTED',
    -- order has been filled and removed from the order book
    'FILLED',
    -- order rejected from the order book.
    -- Possible rejection reasons:
    --  * insufficiency of funds
    --  * FOK or IOC order that cannot be filled
    'REJECTED'
);



-- ── engine/pkg/models/trade_order/order_time_in_force.sql ─────────────────────────────────────────────

-- time constraints imposed on the order
CREATE TYPE order_time_in_force AS ENUM (
    -- good-til-cancelled (GTC) orders require a specific cancelling order, which can persist infinitely
    -- this is the default state for all orders
    'GTC',

    -- an immediate or cancel (IOC) orders are immediately executed or cancelled by the exchange.
    -- Unlike FOK orders, IOC orders allow for partial fills.
    'IOC',

    -- Fill or kill (FOK) orders are usually limit orders that must be executed or cancelled immediately.
    -- Unlike IOC orders, FOK orders require the full quantity to be executed.
    'FOK',

    -- Good till date orders are valid until a certain date. The order gets
    -- canceled at the END of the day, if it is not executed.
    'GTD',

    -- Good till time orders are valid until a certain time with minute precision
    'GTT'
);



